using System.Globalization;
using CleanHome.Payment.Api.Interfaces;
using CleanHome.Payment.Api.Models;
using CleanHome.ServiceDefaults;
using MySqlConnector;
namespace CleanHome.Payment.Api.Repositories;
public sealed class PaymentRepository(DatabaseConnectionFactory connections):IPaymentRepository{
 private const string Columns="booking_id,customer_id,code,amount,method,status,revision,collector_employee_id,collector_user_id,collected_at,paid_at";
 private static async Task<int> Write(MySqlConnection c,MySqlTransaction? t,string sql,CancellationToken ct,params(string,object?)[] args){await using var q=c.Sql(sql,args);q.Transaction=t;return await q.ExecuteNonQueryAsync(ct);}
 private static async Task<PaymentOrder> Read(MySqlConnection c,MySqlTransaction? t,long id,bool locked,CancellationToken ct){await using var q=c.Sql("SELECT "+Columns+" FROM payment_orders WHERE booking_id=@id"+(locked?" FOR UPDATE":""),("id",id));q.Transaction=t;await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new ApiException(404,"Không tìm thấy thanh toán.");return new(r.GetInt64(0),r.GetInt64(1),r.GetString(2),r.GetDecimal(3),r.GetString(4),r.GetString(5),r.GetInt64(6),r.IsDBNull(7)?null:r.GetInt64(7),r.IsDBNull(8)?null:r.GetInt64(8),r.IsDBNull(9)?null:r.GetDateTime(9),r.IsDBNull(10)?null:r.GetDateTime(10));}
 public async Task<PaymentOrder> Read(long id,CancellationToken ct){await using var c=await connections.OpenAsync(ct);return await Read(c,null,id,false,ct);}
 public async Task<PaymentOrder> Enroll(OrderFact f,CancellationToken ct){if(f.Method is not("CASH" or "VNPAY")||f.Amount<=0||decimal.Truncate(f.Amount)!=f.Amount)throw new ApiException(400,"Phương thức hoặc giá VND không hợp lệ.");await using var c=await connections.OpenAsync(ct);await Write(c,null,"INSERT INTO payment_orders(booking_id,customer_id,code,amount,method,status,created_at,updated_at) VALUES(@id,@customer,@code,@amount,@method,@status,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE booking_id=booking_id",ct,("id",f.BookingId),("customer",f.CustomerId),("code",f.Code),("amount",f.Amount),("method",f.Method),("status",f.Method=="VNPAY"?"PENDING":"UNPAID"));var row=await Read(c,null,f.BookingId,false,ct);if(row.CustomerId!=f.CustomerId||row.Amount!=f.Amount||row.Method!=f.Method)throw new ApiException(409,"Snapshot thanh toán khác đơn hàng.");return row;}
 private static Task<int> Audit(MySqlConnection c,MySqlTransaction t,long id,long? actor,string kind,string note,CancellationToken ct,long? payment=null)=>Write(c,t,"INSERT INTO payment_events(booking_id,payment_id,actor_id,event_type,note,created_at) VALUES(@id,@payment,@actor,@kind,@note,UTC_TIMESTAMP(6))",ct,("id",id),("payment",payment),("actor",actor),("kind",kind),("note",note));
 private static Task<int> Status(MySqlConnection c,MySqlTransaction t,long id,string status,CancellationToken ct)=>Write(c,t,"UPDATE payment_orders SET status=@status,revision=revision+1,updated_at=UTC_TIMESTAMP(6),paid_at=IF(@status='PAID',COALESCE(paid_at,UTC_TIMESTAMP(6)),paid_at) WHERE booking_id=@id",ct,("id",id),("status",status));
 private static async Task<PaymentAttempt?> Attempt(MySqlConnection c,MySqlTransaction? t,string where,CancellationToken ct,params(string,object?)[] args){await using var q=c.Sql("SELECT p.id,p.booking_id,p.customer_id,p.amount,p.merchant_ref,p.status,a.payment_url,a.create_date,a.expires_at,p.provider_ref FROM payments p JOIN payment_attempts a ON a.payment_id=p.id WHERE "+where,args);q.Transaction=t;await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;return new(r.GetInt64(0),r.GetInt64(1),r.GetInt64(2),r.GetDecimal(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetDateTime(8),r.IsDBNull(9)?null:r.GetString(9));}
 public async Task<PaymentAttempt?> Attempt(string reference,CancellationToken ct){await using var c=await connections.OpenAsync(ct);return await Attempt(c,null,"p.merchant_ref=@reference",ct,("reference",reference));}
 public async Task<bool> ReserveQuery(string reference,CancellationToken ct){await using var c=await connections.OpenAsync(ct);return await Write(c,null,"UPDATE payment_attempts a JOIN payments p ON p.id=a.payment_id SET a.last_query_at=UTC_TIMESTAMP(6) WHERE p.merchant_ref=@reference AND (a.last_query_at IS NULL OR a.last_query_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 30 SECOND))",ct,("reference",reference))>0;}
 public async Task<bool> ArchiveSafe(long id,bool managed,bool cancelled,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT NOT EXISTS(SELECT 1 FROM payments WHERE booking_id=@id AND status='PENDING') AND NOT EXISTS(SELECT 1 FROM payment_refund_cases WHERE booking_id=@id AND status='pending') AND ((@managed=FALSE AND NOT EXISTS(SELECT 1 FROM payment_orders WHERE booking_id=@id)) OR EXISTS(SELECT 1 FROM payment_orders WHERE booking_id=@id AND (status='REFUNDED' OR (@cancelled=FALSE AND status='PAID') OR (@cancelled=TRUE AND status IN ('UNPAID','FAILED') AND collected_at IS NULL))))",("id",id),("managed",managed),("cancelled",cancelled));return Convert.ToBoolean(await q.ExecuteScalarAsync(ct));}
 public async Task<PaymentAttempt> Create(OrderFact fact,string key,string ip,Func<string,decimal,string,DateTime,string,string> url,CancellationToken ct){await Enroll(fact,ct);await using var c=await connections.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var o=await Read(c,t,fact.BookingId,true,ct);
  var replay=await Attempt(c,t,"p.customer_id=@customer AND p.idempotency_key=@key",ct,("customer",o.CustomerId),("key",key));if(replay is not null){if(replay.BookingId!=o.BookingId)throw new ApiException(409,"Khóa thanh toán đã dùng cho đơn khác.");await t.CommitAsync(ct);return replay;}
  if(o.Method!="VNPAY"||o.Status is not("PENDING" or "FAILED")||fact.WorkStatus!="pending_payment"||fact.CancellationPending||fact.Start<=DateTime.UtcNow.AddMinutes(2))throw new ApiException(409,"Đơn không còn đủ điều kiện tạo giao dịch.");
  var active=await Attempt(c,t,"p.booking_id=@id AND p.status='PENDING' AND a.expires_at>UTC_TIMESTAMP(6) ORDER BY p.id DESC LIMIT 1",ct,("id",o.BookingId));if(active is not null){await t.CommitAsync(ct);return active;}
  // Expiry does not assert failure: a late authenticated success can still be reconciled.
  var reference=Guid.NewGuid().ToString("N");var created=DateTime.UtcNow.AddHours(7).ToString("yyyyMMddHHmmss",CultureInfo.InvariantCulture);var expires=new[]{DateTime.UtcNow.AddMinutes(15),fact.Start}.Min();var target=url(reference,o.Amount,created,expires,ip);
  await Write(c,t,"INSERT INTO payments(booking_id,amount,method,status,merchant_ref,idempotency_key,customer_id,created_at,updated_at) VALUES(@id,@amount,'VNPAY','PENDING',@ref,@key,@customer,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6))",ct,("id",o.BookingId),("amount",o.Amount),("ref",reference),("key",key),("customer",o.CustomerId));await using var identity=c.Sql("SELECT LAST_INSERT_ID()");identity.Transaction=t;var payment=Convert.ToInt64(await identity.ExecuteScalarAsync(ct));
  await Write(c,t,"INSERT INTO payment_attempts(payment_id,create_date,expires_at,payment_url) VALUES(@payment,@created,@expires,@url)",ct,("payment",payment),("created",created),("expires",expires),("url",target));await Status(c,t,o.BookingId,"PENDING",ct);await Audit(c,t,o.BookingId,o.CustomerId,"created","VNPay Sandbox checkout",ct,payment);await t.CommitAsync(ct);return new(payment,o.BookingId,o.CustomerId,o.Amount,reference,"PENDING",target,created,expires,null);
 }
 public async Task<string> Confirm(ProviderResult result,CancellationToken ct){var attempt=await Attempt(result.Reference,ct);if(attempt is null)return "01";await using var c=await connections.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var order=await Read(c,t,attempt.BookingId,true,ct);attempt=await Attempt(c,t,"p.id=@id FOR UPDATE",ct,("id",attempt.Id))??throw new ApiException(404,"Không có giao dịch.");if(attempt.Amount!=result.Amount)return "04";if(attempt.Status=="PAID")return "02";
  var success=result.ResponseCode=="00"&&result.TransactionStatus=="00";if(success&&(string.IsNullOrWhiteSpace(result.TransactionNo)||result.TransactionNo=="0"||!DateTime.TryParseExact(result.PayDate,"yyyyMMddHHmmss",CultureInfo.InvariantCulture,DateTimeStyles.None,out _)))return "99";
  if(!success&&attempt.Status=="FAILED")return "02";
  if(success){await Write(c,t,"UPDATE payments SET status='PAID',provider_ref=@provider,paid_at=UTC_TIMESTAMP(6),version=version+1,updated_at=UTC_TIMESTAMP(6) WHERE id=@id",ct,("provider",result.TransactionNo),("id",attempt.Id));
   await Write(c,t,"UPDATE payment_orders SET paid_at=COALESCE(paid_at,UTC_TIMESTAMP(6)) WHERE booking_id=@id",ct,("id",order.BookingId));
   if(order.Status is "PENDING" or "FAILED")await Status(c,t,order.BookingId,"PAID",ct);
   else {await Write(c,t,"INSERT IGNORE INTO payment_refund_cases(booking_id,payment_id,amount,evidence) VALUES(@id,@payment,@amount,'Late/extra payment requires reconciliation')",ct,("id",order.BookingId),("payment",attempt.Id),("amount",attempt.Amount));if(order.Status=="UNPAID")await Status(c,t,order.BookingId,"REFUND_PENDING",ct);}
  }else{await Write(c,t,"UPDATE payments SET status='FAILED',version=version+1,updated_at=UTC_TIMESTAMP(6) WHERE id=@id AND status<>'PAID'",ct,("id",attempt.Id));if(order.Status=="PENDING"){await using var latest=c.Sql("SELECT MAX(id) FROM payments WHERE booking_id=@id",("id",order.BookingId));latest.Transaction=t;if(Convert.ToInt64(await latest.ExecuteScalarAsync(ct))==attempt.Id)await Status(c,t,order.BookingId,"FAILED",ct);}}
  await Write(c,t,"UPDATE payment_attempts SET response_code=@code,callback_hash=@hash WHERE payment_id=@id",ct,("code",result.ResponseCode),("hash",result.Fingerprint),("id",attempt.Id));await Audit(c,t,order.BookingId,null,success?"vnpay_paid":"vnpay_failed","Verified provider response: "+result.ResponseCode,ct,attempt.Id);await t.CommitAsync(ct);return "00";
 }
 public async Task Mutate(long id,long actor,string action,string note,long? employee,long? user,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var o=await Read(c,t,id,true,ct);string? next=null;
  switch(action){
   case "collector":if(o.Method!="CASH"||o.Status!="UNPAID"||o.CollectedAt is not null)throw new ApiException(409,"Không thể đổi người thu sau khi thu tiền.");if(o.CollectorEmployeeId==employee){await t.CommitAsync(ct);return;}await Write(c,t,"UPDATE payment_orders SET collector_employee_id=@employee,collector_user_id=@user,revision=revision+1 WHERE booking_id=@id",ct,("id",id),("employee",employee),("user",user));break;
   case "collect":if(o.Method!="CASH"||o.CollectorUserId!=actor)throw new ApiException(403,"Bạn không phải người được chỉ định thu tiền.");if(o.Status=="CASH_AWAITING_CONFIRMATION"){await t.CommitAsync(ct);return;}if(o.Status!="UNPAID")throw new ApiException(409,"Không thể thu lại tiền cho đơn này.");await Write(c,t,"UPDATE payment_orders SET collected_at=UTC_TIMESTAMP(6) WHERE booking_id=@id",ct,("id",id));next="CASH_AWAITING_CONFIRMATION";break;
   case "customer_paid":case "customer_disputed":if(o.CustomerId!=actor)throw new ApiException(404,"Không có thanh toán của bạn.");next=action=="customer_paid"?"PAID":"DISPUTED";if(o.Status==next){await t.CommitAsync(ct);return;}if(o.Method!="CASH"||o.Status!="CASH_AWAITING_CONFIRMATION")throw new ApiException(409,"Chưa có xác nhận thu tiền để phản hồi.");break;
   case "resolve_paid":case "resolve_unpaid":if(o.Method!="CASH"||o.Status is not("DISPUTED" or "CASH_AWAITING_CONFIRMATION"))throw new ApiException(409,"Đơn không chờ đối soát tiền mặt.");next=action=="resolve_paid"?"PAID":"UNPAID";if(next=="UNPAID")await Write(c,t,"UPDATE payment_orders SET collected_at=NULL WHERE booking_id=@id",ct,("id",id));break;
   case "refund_request":if(o.Status=="REFUND_PENDING"){await t.CommitAsync(ct);return;}if(o.Status!="PAID")throw new ApiException(409,"Chỉ lập yêu cầu hoàn tiền cho đơn đã xác nhận trả tiền.");await Write(c,t,"INSERT INTO payment_refund_cases(booking_id,payment_id,amount,evidence) SELECT @id,MIN(id),@amount,@note FROM payments WHERE booking_id=@id AND status='PAID'",ct,("id",id),("amount",o.Amount),("note",note));next="REFUND_PENDING";break;
   default:throw new ApiException(400,"Thao tác không hợp lệ.");
  }
  if(next is not null)await Status(c,t,id,next,ct);
  if(next=="PAID"&&o.Method=="CASH")await Write(c,t,"INSERT INTO payments(booking_id,amount,method,status,merchant_ref,idempotency_key,customer_id,paid_at,created_at,updated_at) VALUES(@id,@amount,'CASH','PAID',@ref,@ref,@customer,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6),UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE id=id",ct,("id",id),("amount",o.Amount),("ref","CASH-"+id),("customer",o.CustomerId));
  await Audit(c,t,id,actor,action,note,ct);await t.CommitAsync(ct);
 }
 public async Task Cancel(long id,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var o=await Read(c,t,id,true,ct);if(o.Status is "PAID" or "CASH_AWAITING_CONFIRMATION" or "DISPUTED"){
  await Write(c,t,"INSERT INTO payment_refund_cases(booking_id,payment_id,amount,evidence) SELECT @id,p.id,@amount,'Cancelled order: admin assessment required' FROM (SELECT 1) x LEFT JOIN payments p ON p.booking_id=@id AND p.status='PAID' WHERE NOT EXISTS(SELECT 1 FROM payment_refund_cases f WHERE f.booking_id=@id AND f.status='pending')",ct,("id",id),("amount",o.Amount));await Status(c,t,id,"REFUND_PENDING",ct);await Audit(c,t,id,null,"refund_pending","Cancellation requires reconciliation, no automatic refund assertion",ct);
 }else if(o.Status is "PENDING" or "FAILED"){await Status(c,t,id,"UNPAID",ct);await Audit(c,t,id,null,"cancelled_unpaid","Order cancelled before verified payment",ct);}await t.CommitAsync(ct);}
 public async Task<IReadOnlyList<long>> Due(CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT booking_id FROM payment_orders ORDER BY COALESCE(last_checked_at,'2000-01-01'),booking_id LIMIT 20");await using var r=await q.ExecuteReaderAsync(ct);var ids=new List<long>();while(await r.ReadAsync(ct))ids.Add(r.GetInt64(0));return ids;}
 public async Task SyncMark(long id,long revision,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await Write(c,null,"UPDATE payment_orders SET synced_revision=GREATEST(synced_revision,@revision),last_checked_at=UTC_TIMESTAMP(6) WHERE booking_id=@id",ct,("id",id),("revision",revision));}
 public async Task<object> Audit(long id,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT id,payment_id,actor_id,event_type,note,created_at FROM payment_events WHERE booking_id=@id ORDER BY id DESC LIMIT 200",("id",id));var events=await q.RowsAsync(ct);await using var attempts=c.Sql("SELECT id,merchant_ref,provider_ref,amount,status,created_at,paid_at FROM payments WHERE booking_id=@id ORDER BY id DESC LIMIT 100",("id",id));var transactions=await attempts.RowsAsync(ct);await using var refunds=c.Sql("SELECT id,payment_id,amount,status,evidence,resolved_by,resolved_at FROM payment_refund_cases WHERE booking_id=@id ORDER BY id DESC",("id",id));return new{events,transactions,refunds=await refunds.RowsAsync(ct)};}
 public async Task<object> AdminList(int page,string? status,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT "+Columns+" FROM payment_orders WHERE (@status IS NULL OR status=@status) ORDER BY booking_id DESC LIMIT 30 OFFSET @offset",("status",status),("offset",(page-1)*30));var items=await q.RowsAsync(ct);await using var summary=c.Sql("SELECT COUNT(*) AS orders,SUM(method='VNPAY') AS vnpay_orders,SUM(method='CASH') AS cash_orders,COALESCE(SUM(amount),0) AS order_value,COALESCE(SUM(IF(paid_at IS NOT NULL AND status<>'REFUNDED',amount,0)),0) AS collected,COALESCE(SUM(IF(status IN ('UNPAID','PENDING','FAILED','CASH_AWAITING_CONFIRMATION','DISPUTED'),amount,0)),0) AS outstanding,COALESCE(SUM(IF(method='CASH' AND collected_at IS NOT NULL,amount,0)),0) AS cash_collected,COALESCE(SUM(status='DISPUTED'),0) AS disputes FROM payment_orders");var totals=await summary.RowsAsync(ct);await using var refunds=c.Sql("SELECT COALESCE(SUM(amount),0) AS pending_refunds FROM payment_refund_cases WHERE status='pending'");return new{items,page,summary=totals,refundSummary=await refunds.RowsAsync(ct)};}
 public async Task<IReadOnlyList<string>> PendingAttempts(CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT p.merchant_ref FROM payments p JOIN payment_attempts a ON a.payment_id=p.id WHERE p.status='PENDING' AND STR_TO_DATE(a.create_date,'%Y%m%d%H%i%s')<DATE_SUB(DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 7 HOUR),INTERVAL 2 MINUTE) ORDER BY COALESCE(a.last_query_at,'2000-01-01'),p.id LIMIT 5");await using var r=await q.ExecuteReaderAsync(ct);var refs=new List<string>();while(await r.ReadAsync(ct))refs.Add(r.GetString(0));return refs;}
 public async Task Refund(long id,long caseId,long actor,string evidence,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var order=await Read(c,t,id,true,ct);await using var query=c.Sql("SELECT status FROM payment_refund_cases WHERE id=@case AND booking_id=@id FOR UPDATE",("case",caseId),("id",id));query.Transaction=t;var status=await query.ExecuteScalarAsync(ct);if(status is null)throw new ApiException(404,"Không có yêu cầu hoàn tiền.");if(Convert.ToString(status)=="refunded"){await t.CommitAsync(ct);return;}await Write(c,t,"UPDATE payment_refund_cases SET status='refunded',evidence=@evidence,resolved_by=@actor,resolved_at=UTC_TIMESTAMP(6) WHERE id=@case",ct,("case",caseId),("evidence",evidence),("actor",actor));if(order.Status=="REFUND_PENDING"){await using var pending=c.Sql("SELECT COUNT(*) FROM payment_refund_cases WHERE booking_id=@id AND status='pending'",("id",id));pending.Transaction=t;if(Convert.ToInt64(await pending.ExecuteScalarAsync(ct))==0)await Status(c,t,id,"REFUNDED",ct);}await Audit(c,t,id,actor,"manual_refund_confirmed",evidence,ct);await t.CommitAsync(ct);}
}
